-- Brand strategy (personas, pains, angles by awareness level, format matrix, pillars).
-- Generated by a plan.generate job as a draft version; a business owner or admin approves it.
-- Versions are immutable: a new generation adds a version, approval only stamps the row.
CREATE TABLE app.brand_strategies (
 id uuid PRIMARY KEY, organization_id uuid NOT NULL, brand_id uuid NOT NULL,
 version integer NOT NULL CHECK(version>0),
 status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')),
 strategy jsonb NOT NULL CHECK(jsonb_typeof(strategy)='object' AND octet_length(strategy::text)<=120000),
 sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),
 brain_id uuid NOT NULL, job_id uuid NOT NULL UNIQUE,
 skill_manifest jsonb NOT NULL CHECK(octet_length(skill_manifest::text)<=100000),
 created_by uuid NOT NULL REFERENCES auth."user"(id), created_at timestamptz NOT NULL DEFAULT now(),
 approved_by uuid REFERENCES auth."user"(id), approved_at timestamptz,
 UNIQUE(organization_id,brand_id,id), UNIQUE(organization_id,brand_id,version),
 FOREIGN KEY(organization_id,brand_id) REFERENCES app.brands(organization_id,id),
 FOREIGN KEY(organization_id,brand_id,job_id) REFERENCES app.jobs(organization_id,brand_id,id),
 FOREIGN KEY(organization_id,brand_id,brain_id) REFERENCES app.brand_brain_versions(organization_id,brand_id,id),
 CHECK((status='draft' AND approved_by IS NULL AND approved_at IS NULL) OR (status='approved' AND approved_by IS NOT NULL AND approved_at IS NOT NULL))
);
ALTER TABLE app.brand_strategies ENABLE ROW LEVEL SECURITY;
ALTER TABLE app.brand_strategies FORCE ROW LEVEL SECURITY;
CREATE POLICY strategy_read ON app.brand_strategies FOR SELECT TO desvio_app USING(app.can_access(organization_id) AND app.brand_matches(brand_id) AND app.business_access(organization_id,brand_id));
CREATE POLICY strategy_approve ON app.brand_strategies FOR UPDATE TO desvio_app
 USING(app.can_access(organization_id,true) AND app.brand_matches(brand_id) AND app.creative_reviewer(organization_id,brand_id) AND status='draft')
 WITH CHECK(status='approved' AND approved_by=app.actor() AND approved_at IS NOT NULL);
GRANT SELECT ON app.brand_strategies TO desvio_app;
GRANT UPDATE(status,approved_by,approved_at) ON app.brand_strategies TO desvio_app;
-- The planning worker may add the draft produced by its own job and nothing else.
CREATE POLICY strategy_worker_read ON app.brand_strategies FOR SELECT TO desvio_worker USING(app.planning_scope(organization_id,brand_id));
CREATE POLICY strategy_worker_insert ON app.brand_strategies FOR INSERT TO desvio_worker
 WITH CHECK(app.planning_scope(organization_id,brand_id) AND job_id=app.job_context() AND status='draft' AND approved_by IS NULL AND approved_at IS NULL);
GRANT SELECT,INSERT ON app.brand_strategies TO desvio_worker;
CREATE POLICY strategy_operator ON app.brand_strategies TO CURRENT_USER USING(true) WITH CHECK(true);
